import React, { useState } from 'react';
import './App.css';

const template = `
<br /><br /><br /><br /><br /><br /><br /><br /><br /><br /><br /><br />
<table style="width:100%;">
  <tr>
    <td style="width:35%;"><b>Ref. No.TP/SU[ref-batch]/25-</b></td>
    <td style="width:30%;">&nbsp;</td>
    <td style="width:35%; text-align:right;"><b>Date: ____________</b></td>
  </tr>
</table>
<br /><br />
<table style="width:100%;">
  <tr>
    <td style="width:33%;">&nbsp;</td>
    <td align="center" style="padding-top:40px; padding-bottom:5px;">
      <b style="font-size:1rem;">No Objection Certificate</b>
    </td>
    <td style="width:10%;">&nbsp;</td>
  </tr>
</table>
<br />
This is to certify that <strong>[name]</strong>, [childOf] <strong>[fathers name]</strong>, bearing <strong>University Roll No [roll no]</strong>. is a bona fide student of Srinath University, Jamshedpur. [HeShe] is currently enrolled in the <strong>[sem]</strong> of the <strong>[course name]</strong>[specializationSection], as part of the Academic Batch: <strong>[academic batch]</strong>.<br /><br />
The university has no objection to [pronoun] undertaking a <strong>summer internship</strong> at <strong>[company name]</strong>, <strong>[company address]</strong>. The internship is scheduled to take place from <strong>[internshipDuration]</strong>.<br /><br />
This certificate is issued upon request for official purposes.<br /><br /><br />
<div style="text-align: left;">
<strong>Subhadeep Bhadra<br />
Director<br />
Srinath Centre for Career Development<br />
Srinath University, Jamshedpur</strong>
</div>
`;

const courseOptions = {
    BBA: {
        courseName: "Bachelor of Business Administration (BBA)",
        academicBatch: "2023-2026", 
        refBatch: "23-26",
        showSpecialization: true,
        internshipDuration: "16th June 2025 to 16th August 2025",
        sem: "Fourth Semester"
    },
    BCA: {
        courseName: "Bachelor of Computer Applications (BCA)",
        academicBatch: "2023-2026",
        refBatch: "23-26",
        showSpecialization: false,
        internshipDuration: "15th June 2025 to 15th September 2025",
        sem: "Fourth Semester"
    },
    BCOM: {
        courseName: "Bachelor of Commerce (B.COM)",
        academicBatch: "2023-2026",
        refBatch: "23-26",
        showSpecialization: true,
        internshipDuration: "15th June 2025 to 15th August 2025",
        sem: "Fourth Semester"
    },
    BTECH: {
        courseName: "Bachelor of Technology (BTECH)",
        academicBatch: "2022-2026",
        refBatch: "22-26",
        showSpecialization: true,
        internshipDuration: "1st August 2025 to 1st October 2025",
        sem: "Sixth Semester"
    },
    MCA: {
        courseName: "Master of Computer Applications (MCA)",
        academicBatch: "2024-2026",
        refBatch: "24-26",
        showSpecialization: false,
        internshipDuration: "16th June 2025 to 16th September 2025",
        sem: "Second Semester",
    },
    MBA: {
        courseName: "Master of Business Administration (MBA)",
        academicBatch: "2024-2026",
        refBatch: "24-26",
        showSpecialization: true,
        internshipDuration: "16th June 2025 to 16th August 2025",
        sem: "Second Semester"
    },
    DIPLOMA: {
        courseName: "Diploma",
        academicBatch: "2023-2026",
        refBatch: "23-26",
        showSpecialization: true,
        internshipDuration: "1st August 2025 to 1st October 2025",
        sem: "Fourth Semester"
    },
    DIPLOMA1YEAR: {
        courseName: "Diploma 1st Year", // Button label
        displayName: "Diploma",         // Certificate label
        academicBatch: "2024-2027",
        refBatch: "24-27",
        showSpecialization: true,
        internshipDuration: "1st August 2025 to 1st September 2025",
        sem: "Second Semester"
    }
};

function App() {
    const [form, setForm] = useState({
        name: '',
        fathersName: '',
        rollNo: '',
        courseName: '',
        specialization: '',
        academicBatch: '',
        companyName: '',
        companyAddress: ''
    });
    const [selectedCourse, setSelectedCourse] = useState('');
    const [gender, setGender] = useState('male');

    // No auto-title-case or uppercase logic
    const handleChange = (e) => {
        const { name, value } = e.target;
        setForm({ ...form, [name]: value });
    };

    const handleCourseSelect = (courseKey) => {
        const course = courseOptions[courseKey];
        setSelectedCourse(courseKey);
        setForm((prev) => ({
            ...prev,
            courseName: course.displayName || course.courseName, // Use displayName for certificate
            academicBatch: course.academicBatch,
            specialization: '' // reset specialization on course change
        }));
    };

    // Gender-specific replacements
    const childOf = gender === 'male' ? 'son of' : 'daughter of';
    const pronoun = gender === 'male' ? 'his' : 'her';
    const heShe = gender === 'male' ? 'He' : 'She';

    // Specialization section logic
    let specializationSection = '';
    if (selectedCourse && courseOptions[selectedCourse].showSpecialization) {
        specializationSection = ` Specialization: <strong>${form.specialization || '[Specialization]'}</strong>`;
    }

    // Internship duration logic
    const internshipDuration =
        (selectedCourse && courseOptions[selectedCourse].internshipDuration) ||
        "15th June 2025 to 15th August 2025";

    // Semester logic
    const semister =
        (selectedCourse && courseOptions[selectedCourse].sem) ||
        "[sem]";

    // Ref batch logic
    const refBatch =
        (selectedCourse && courseOptions[selectedCourse].refBatch) ||
        "[ref-batch]";

    let filledTemplate = template
        .replace('[name]', form.name || '[name]')
        .replace('[fathers name]', form.fathersName || '[fathers name]')
        .replace('[roll no]', form.rollNo || '[roll no]')
        .replace('[course name]', form.courseName || '[course name]')
        .replace('[academic batch]', form.academicBatch || '[academic batch]')
        .replace('[company name]', form.companyName || '[company name]')
        .replace('[company address]', form.companyAddress || '[company address]')
        .replace('[childOf]', childOf)
        .replace('[pronoun]', pronoun)
        .replace('[HeShe]', heShe)
        .replace('[specializationSection]', specializationSection)
        .replace('[internshipDuration]', internshipDuration)
        .replace('[sem]', semister)
        .replace('[ref-batch]', refBatch);

    // Copy as HTML (preserves bold when pasting into Word)
    const handleCopy = () => {
        const html = filledTemplate;
        const plainText = filledTemplate
            .replace(/<br\s*\/?>/gi, '\n')
            .replace(/<strong>/g, '')
            .replace(/<\/strong>/g, '');
        if (navigator.clipboard && window.ClipboardItem) {
            const blobHtml = new Blob([html], { type: 'text/html' });
            const blobText = new Blob([plainText], { type: 'text/plain' });
            const data = {
                'text/html': blobHtml,
                'text/plain': blobText,
            };
            navigator.clipboard.write([new window.ClipboardItem(data)])
                .catch(() => {
                    navigator.clipboard.writeText(plainText);
                });
        } else {
            navigator.clipboard.writeText(plainText);
        }
    };

    return (
        <div className="container">
            <h1>NOC Certificate Editor</h1>
            <div className="gender-buttons" style={{ display: 'flex', gap: '10px', justifyContent: 'center', marginBottom: '16px' }}>
                <button
                    type="button"
                    className={gender === 'male' ? 'selected' : ''}
                    onClick={() => setGender('male')}
                >
                    Male
                </button>
                <button
                    type="button"
                    className={gender === 'female' ? 'selected' : ''}
                    onClick={() => setGender('female')}
                >
                    Female
                </button>
            </div>
            <div className="course-buttons">
                {Object.keys(courseOptions).map((key) => (
                    <button
                        key={key}
                        type="button"
                        className={selectedCourse === key ? 'selected' : ''}
                        onClick={() => handleCourseSelect(key)}
                    >
                        {courseOptions[key].courseName}
                    </button>
                ))}
            </div>
            <div className="form-section" style={{maxWidth: "500px", margin: "32px auto", background: "#f8f8f8", padding: "24px", borderRadius: "10px", boxShadow: "0 2px 8px #eee"}}>
                <form className="form" style={{display: "flex", flexDirection: "column", gap: "16px"}}>
                    <label>
                        Name:
                        <input type="text" name="name" value={form.name} onChange={handleChange} style={{width: "100%", padding: "8px", marginTop: "4px"}} />
                    </label>
                    <label>
                        Father's Name:
                        <input type="text" name="fathersName" value={form.fathersName} onChange={handleChange} style={{width: "100%", padding: "8px", marginTop: "4px"}} />
                    </label>
                    <label>
                        University Roll No:
                        <input type="text" name="rollNo" value={form.rollNo} onChange={handleChange} style={{width: "100%", padding: "8px", marginTop: "4px"}} />
                    </label>
                    <label>
                        Course Name:
                        <input type="text" name="courseName" value={form.courseName} readOnly style={{width: "100%", padding: "8px", marginTop: "4px", background: "#e9ecef"}} />
                    </label>
                    {selectedCourse && courseOptions[selectedCourse].showSpecialization && (
                        <label>
                            Specialization:
                            <input type="text" name="specialization" value={form.specialization} onChange={handleChange} style={{width: "100%", padding: "8px", marginTop: "4px"}} />
                        </label>
                    )}
                    <label>
                        Academic Batch:
                        <input type="text" name="academicBatch" value={form.academicBatch} readOnly style={{width: "100%", padding: "8px", marginTop: "4px", background: "#e9ecef"}} />
                    </label>
                    <label>
                        Company Name:
                        <input type="text" name="companyName" value={form.companyName} onChange={handleChange} style={{width: "100%", padding: "8px", marginTop: "4px"}} />
                    </label>
                    <label>
                        Company Address:
                        <input type="text" name="companyAddress" value={form.companyAddress} onChange={handleChange} style={{width: "100%", padding: "8px", marginTop: "4px"}} />
                    </label>
                </form>
                <button className="copy-btn" onClick={handleCopy} style={{
                    marginTop: "24px",
                    padding: "12px 24px",
                    fontSize: "1.1em",
                    background: "#007bff",
                    color: "#fff",
                    border: "none",
                    borderRadius: "6px",
                    cursor: "pointer",
                    fontWeight: "bold"
                }}>Copy Certificate</button>
            </div>
            <div className="preview-section" style={{maxWidth: "900px", margin: "0 auto"}}>
                <h2 style={{marginBottom: "16px"}}>Preview</h2>
                <pre className="document-box" style={{
                    fontFamily: "'Consolas', 'Courier New', monospace",
                    background: "#fff",
                    padding: "32px",
                    minHeight: "700px",
                    maxHeight: "1200px",
                    width: "100%",
                    fontSize: "1.1em",
                    overflow: "auto",
                    boxSizing: "border-box",
                    border: "1px solid #ccc",
                    borderRadius: "10px"
                }}>
                    <span dangerouslySetInnerHTML={{ __html: filledTemplate }} />
                </pre>
            </div>
        </div>
    );
}

export default App;